.layout {
  display: grid;
  gap: 12px;
  grid-template-areas:
    "head head"
    "side main"
    "foot foot";
  grid-template-columns: 200px 1fr;
}

.layout header { grid-area: head; }
.layout aside { grid-area: side; }
.layout main { grid-area: main; }
.layout footer { grid-area: foot; }

.cards {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 12px;
}
